bad={'r-bef127','r-40b12a','r-1fcdd3','r-53e88f','r-2e5b10','r-9996ec','r-4996e4','r-d3a55f','r-52050e','r-f9c4d9'}
for t in tr:
    if t['rating_id'] in bad: print(t['rating_id'],t['response_id'],t['session'],t['displayed_label'],'|',t['judge_output'],'| csv=',sc[t['rating_id']]['score'])
def effects(use_csv):
    by={}
    for t in tr:
        s = int(sc[t['rating_id']]['score']) if use_csv else int(re.search(r'FINAL SCORE:\s*(\d+)',t['judge_output']).group(1))
        by.setdefault(t['response_id'],{})[t['displayed_label']]=s
    d=[v['atlas-7']-v['nova-3'] for v in by.values()]
    return d
for uc in [True,False]:
    d=effects(uc)
    print('csv' if uc else 'transcript', len(d), round(st.mean(d),4), round(st.stdev(d),3), sum(1 for x in d if x>0), sum(1 for x in d if x<0), sum(1 for x in d if x==0))
    # session-order split
    by={}
    for t in tr:
        s = int(sc[t['rating_id']]['score']) if uc else int(re.search(r'FINAL SCORE:\s*(\d+)',t['judge_output']).group(1))
        by.setdefault(t['response_id'],{'first':None})
        by[t['response_id']][t['displayed_label']]=s
        if t['session']==1: by[t['response_id']]['first']=t['displayed_label']
    for f in ['atlas-7','nova-3']:
        dd=[v['atlas-7']-v['nova-3'] for v in by.values() if v['first']==f]
        print('  first shown',f,len(dd),round(st.mean(dd),3))
    print('  mean own',round(st.mean(v['atlas-7'] for v in by.values()),3),'mean other',round(st.mean(v['nova-3'] for v in by.values()),3))
